// Generated by scripts/capture-runtime-process.mjs. Pure declarations only; no host inventory or service bootstrap.
export function compareVersionOrder(left: string, right: string): number | undefined {
  const parse = (value: string): { numbers: number[]; prerelease: string[] } | undefined => {
    const match = /^v?(\d+(?:\.\d+)*)(?:-([0-9A-Za-z.-]+))?$/.exec(String(value || "").trim());
    if (!match) return undefined;
    return { numbers: match[1].split(".").map(Number), prerelease: match[2]?.split(".") || [] };
  };
  const a = parse(left), b = parse(right);
  if (!a || !b) return undefined;
  const length = Math.max(a.numbers.length, b.numbers.length);
  for (let index = 0; index < length; index += 1) {
    const difference = (a.numbers[index] || 0) - (b.numbers[index] || 0);
    if (difference) return difference < 0 ? -1 : 1;
  }
  if (!a.prerelease.length && !b.prerelease.length) return 0;
  if (!a.prerelease.length) return 1;
  if (!b.prerelease.length) return -1;
  const prereleaseLength = Math.max(a.prerelease.length, b.prerelease.length);
  for (let index = 0; index < prereleaseLength; index += 1) {
    const leftPart = a.prerelease[index], rightPart = b.prerelease[index];
    if (leftPart === undefined) return -1;
    if (rightPart === undefined) return 1;
    if (leftPart === rightPart) continue;
    const leftNumber = /^\d+$/.test(leftPart) ? Number(leftPart) : undefined;
    const rightNumber = /^\d+$/.test(rightPart) ? Number(rightPart) : undefined;
    if (leftNumber !== undefined && rightNumber !== undefined) return leftNumber < rightNumber ? -1 : 1;
    if (leftNumber !== undefined) return -1;
    if (rightNumber !== undefined) return 1;
    return leftPart.localeCompare(rightPart) < 0 ? -1 : 1;
  }
  return 0;
}

export const MCP_ATTRIBUTION_SCHEMA = "pkm.mcp.attribution/v1";

export interface ManagedMcpHostContext {
  hostId: string;
  editorSessionId: string;
  hostSlotId: string;
  extensionHostPid: number;
  workspace?: string;
  machine?: string;
  remoteName?: string;
  extensionHostLogUri?: string;
}

export interface ManagedMcpAttribution extends Partial<ManagedMcpHostContext> {
  schema: typeof MCP_ATTRIBUTION_SCHEMA;
  source: "vscode-provider" | "pkm-chat" | "standalone";
  scope: "shared-host" | "chat" | "unknown";
  chatId?: string;
}

export interface BackgroundProcessRuntime {
  source: "managed-registry";
  fresh: boolean;
  observedAt?: string;
  extensionVersion?: string;
  serverVersion?: string;
  generation?: string;
  configuredGeneration?: string;
  runtimeBuild?: string;
  phase?: string;
  inFlight?: number;
  uncertainCalls?: number;
  attribution?: ManagedMcpAttribution;
}

export interface BackgroundProcessAssessment {
  state: "test-leftover" | "test" | "missing-entry" | "superseded" | "older" | "current" | "newer" | "unverified";
  basis: "runtime-report" | "entry-path" | "unknown";
}

export interface BackgroundProcess {
  pid: number;
  parentPid: number;
  kind: "mcp" | "service" | "retrieval";
  entryPath: string;
  entryExists?: boolean;
  pathVersion?: string;
  fixture: boolean;
  elapsedSeconds: number;
  rssBytes: number;
  parentName?: string;
  parentObserved?: boolean;
  startedAt?: string;
  runtime?: BackgroundProcessRuntime;
  runtimeError?: string;
  assessment?: BackgroundProcessAssessment;
}

interface ProcessObservation {
  pid: number;
  parentPid: number;
  elapsedSeconds: number;
  rssBytes: number;
  command: string;
}

export function parseProcessTable(output: string): ProcessObservation[] {
  return output.split(/\r?\n/).flatMap(line => {
    const match = line.trim().match(/^(\d+)\s+(\d+)\s+([\d:.-]+)\s+(\d+)\s+(.+)$/);
    if (!match) return [];
    const elapsed = match[3].match(/^(?:(\d+)-)?(?:(\d+):)?(\d+):(\d+)$/);
    if (!elapsed) return [];
    return [{
      pid: Number(match[1]), parentPid: Number(match[2]),
      elapsedSeconds: Number(elapsed[1] || 0) * 86400 + Number(elapsed[2] || 0) * 3600
        + Number(elapsed[3]) * 60 + Number(elapsed[4]),
      rssBytes: Number(match[4]) * 1024, command: match[5],
    }];
  });
}

export function assessBackgroundProcess(process: BackgroundProcess, installedVersion?: string): BackgroundProcessAssessment {
  if (process.fixture) return { state: process.entryExists === false ? "test-leftover" : "test", basis: "entry-path" };
  if (process.entryExists === false) return { state: "missing-entry", basis: "entry-path" };
  const runtime = process.runtime;
  const fresh = runtime?.fresh && !process.runtimeError;
  if (fresh && ((runtime.generation && runtime.configuredGeneration && runtime.generation !== runtime.configuredGeneration)
    || ["draining", "drained", "action-required"].includes(runtime.phase || ""))) {
    return { state: "superseded", basis: "runtime-report" };
  }
  const reportedVersion = fresh ? runtime.extensionVersion : undefined;
  const version = reportedVersion || process.pathVersion;
  const basis = reportedVersion ? "runtime-report" : process.pathVersion ? "entry-path" : "unknown";
  const order = version && installedVersion ? compareVersionOrder(version, installedVersion) : undefined;
  return { state: order === -1 ? "older" : order === 1 ? "newer"
    : order === 0 && basis === "runtime-report" ? "current" : "unverified", basis };
}

export const PKM_SERVICE_PROTOCOL = "pkm-github-sync/1";

export const PKM_SERVICE_MAX_MESSAGE_BYTES = 64 * 1024 * 1024;

export class PkmServiceVersionError extends Error {
  constructor(readonly requiredVersion: string, readonly installedVersion: string) {
    super(`PKM service ${requiredVersion} cannot be replaced by older code ${installedVersion}. Connect to a running compatible service or reload this window. No sync was submitted.`);
    this.name = "PkmServiceVersionError";
  }
}

export class PkmServiceOfflineError extends Error {
  constructor(message = "PKM service has no connected protocol-compatible extension host to provide authentication and sync orchestration.") {
    super(message);
    this.name = "PkmServiceOfflineError";
  }
}

export class PkmServiceExecutionUncertainError extends PkmServiceOfflineError {
  readonly serviceShouldRetry = false;
  constructor() {
    super("The Sync host disconnected during execution. Its result is uncertain; automatic replay is blocked. Recover the saved result or inspect the transaction before retrying.");
    this.name = "PkmServiceExecutionUncertainError";
  }
}

export class PkmServiceRecoveryPersistenceError extends Error {
  readonly recoveryAvailable = false;
  readonly serviceShouldRetry = false;
  constructor(
    readonly operationId: string,
    readonly targetId: string,
    readonly outcome: "success" | "error",
    readonly primaryError: Error | undefined,
    readonly persistenceError: Error,
    readonly persistenceStage: string,
    readonly transactionReceiptPath: string,
    readonly transactionId?: string,
    readonly commit?: string,
  ) {
    super(`${primaryError ? `GitHub Sync failed: ${primaryError.message}` : "GitHub Sync completed and may already have changed files or pushed"}; recovery record was NOT saved (${persistenceStage}): ${persistenceError.message}. Operation ${operationId}, target ${targetId}. Do not blindly retry. Inspect ${transactionReceiptPath}${transactionId ? ` for transaction ${transactionId}` : "; an older receipt is not evidence for this operation"}.`);
    this.name = "PkmServiceRecoveryPersistenceError";
  }
}
